-- ============================================================
-- MIGRACIA: presne rezove tvary beachvlajok (Blade/Basic/Wing/Wave/Feather)
-- z realnych vyrobnych strihov (PDF, 1:1 realna velkost). Kazda velkost ma:
--   cut_path   = presny orezovy tvar (cervena) - presne podla PDF strihu
--   bleed_path = spadavka pre grafiku, 5cm DOOKOLA NAVIAC za orez (novy stlpec)
--   safe_path  = bezpecna zona, 4cm DOOKOLA DOVNUTRA od orezu
-- viewbox teraz zahrna aj 5cm okraj navyse na kazdej strane (aby sa spadavka
-- zmestila do platna) - spotreba_m2 pocita LEN skutocnu plochu vlajky (bez spadavky).
-- Existujuce tvary (cepel/pierko/kvapka/kridlo) sa PREPISU na presne rozmery,
-- kod/nazov ostavaju rovnake. "kridlo" (wing) nema velkost S v podkladoch - ostava
-- nedotknuta (povodne priblizne data), kym nedodas aj "wing S" strih.
-- "basic" je novy 5. tvar, pridava sa. Spustit v Supabase SQL editore.
-- Bezpecne spustit opakovane (idempotentne cez ON CONFLICT).
-- ============================================================

alter table vlajka_tvar_rozmery add column if not exists bleed_path text;

insert into vlajka_tvary (kod, nazov, ikona, poradie) values ('basic', 'Basic', 'flag', 10) on conflict (kod) do nothing;

